"""Warehouse fulfilment and packing slip generation."""

from __future__ import annotations

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


class FulfilmentService:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def get_packing_slip(self, order_id: str) -> dict:
        order = self._orders.get(order_id)
        if order is None:
            raise OrderNotFound(order_id)
        if order.status == "cancelled":
            raise Conflict(f"order {order_id} is cancelled")
        customer = self._customers.get(order.customer_id)
        customer_name = customer.name if customer is not None else ""
        lines = [
            {
                "sku": item.sku,
                "name": self._catalog.get(item.sku).name if self._catalog.get(item.sku) else "",
                "quantity": item.quantity
            }
            for item in order.items
        ]
        return {
            "order_id": order.order_id,
            "customer_name": customer_name,
            "lines": lines
        }

    def get_low_stock(self, threshold: int) -> list[dict]:
        products = [
            {
                "sku": p.sku,
                "name": p.name,
                "on_hand": self._stock.get(p.sku)
            }
            for p in self._catalog.list_all()
            if p.active and self._stock.get(p.sku) < threshold
        ]
        return sorted(products, key=lambda p: (p["on_hand"], p["sku"]))

    def restock(self, sku: str, quantity: int) -> dict:
        product = self._catalog.get(sku)
        if product is None or not product.active:
            raise ProductNotFound(sku)
        new_level = self._stock.get(sku) + quantity
        self._stock.set(sku, new_level)
        return {"sku": sku, "on_hand": new_level}

    def get_fulfilment_summary(self) -> dict:
        open_orders = 0
        units_to_pick = 0
        for order in self._orders.list_all():
            if order.status != "cancelled":
                open_orders += 1
                units_to_pick += sum(item.quantity for item in order.items)
        low_stock_products = sum(
            1 for p in self._catalog.list_all()
            if p.active and self._stock.get(p.sku) < 5
        )
        return {
            "open_orders": open_orders,
            "units_to_pick": units_to_pick,
            "low_stock_products": low_stock_products
        }
